mapper.select:
SELECT t.LN_ID, t.HD_ID, t.CONTRACT_ID, (select c.contract_number from con_contract c where c.contract_id = t.contract_id)contract_id_n, t.SOURCE_ID, t.SOURCE_TYPE, t.ET_DATE, t.ET_AMOUNT, t.ET_EXEMPT_AMOUNT, t.ET_PRE_AMOUNT, t.RENTAL_RESIDUAL_AMOUNT, (select q.vat_rate from con_contract c,prj_quotation q where c.contract_id = t.contract_id and c.quotation_id = q.quotation_id)int_rate, ( SELECT q.lease_times FROM con_contract c, prj_quotation q WHERE c.contract_id = t.contract_id AND c.quotation_id = q.quotation_id ) lease_times FROM hls_duration_ln t
and t.hd_id = #{hdId}
and t.ln_id = #{lnId}
order by t.ln_id

SELECT * FROM (SELECT ln.*, c.contract_number, c.contract_number AS contract_id_n, c.contract_name, c.contract_number AS cashflow_id_n, (select p.contract_number from prj_project p where p.project_id = c.project_id) prj_con_number, ccc.times, ccc.due_date, ccc.due_amount, (ccc.due_amount - nvl(ccc.received_amount, 0)) residual_amount, (ccc.interest - nvl(ccc.received_interest, 0)) residual_interest, ccc.cf_item, (SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = ccc.cf_item) cf_item_n, bp.bp_name, ee.name AS employee_name, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'CON.CONTRACT_STATUS' AND v.code_value = c.contract_status) contract_status_n, nvl(c.finance_amount, 0) finance_amount, nvl((SELECT SUM(cc.principal - nvl(cc.received_principal, 0)) FROM con_contract_cashflow cc WHERE cc.contract_id = c.contract_id AND cc.cf_item = 1 AND cc.cf_status = 'RELEASE'), 0) outstanding_principal, nvl(c.overdue_max_days, 0) overdue_max_days, c.project_id, (select pp.ref_project_id from prj_project pp where pp.project_id = c.project_id) ref_project_id, (select pp.contract_name from prj_project pp where pp.project_id = c.project_id) prjConName FROM hls_duration_ln ln LEFT JOIN con_contract c ON ln.contract_id = c.contract_id LEFT JOIN hls_bp_master bp ON c.tenant_id = bp.bp_id LEFT JOIN fnd_employee ee ON c.employee_id = ee.employee_id LEFT JOIN con_contract_cashflow ccc ON ln.cashflow_id = ccc.cashflow_id) t
t.hd_id = #{hdId}
and t.source_id = #{sourceId}
and t.source_type = #{sourceType}

SELECT ln.ln_id, ln.hd_id, ln.source_id, pp.project_id, pp.ref_project_id, pp.contract_number AS source_id_n, pp.contract_name AS prj_con_name, (SELECT bp.bp_name FROM hls_bp_master bp WHERE bp.bp_id = pp.tenant_id) bp_name, (SELECT fe.name FROM fnd_employee fe WHERE fe.employee_id = pp.employee_id) employee_name, pp.finance_amount FROM hls_duration_ln ln, prj_project pp
ln.hd_id = #{hdId} and ln.source_id = pp.project_id
and ln.source_type = #{sourceType}

SELECT ln.ln_id, ln.hd_id, ccc.cashflow_id, ccc.contract_id, ccc.times, ccc.due_date, ccc.cf_item, cc.contract_number, (SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = ccc.cf_item) cf_item_n, ccc.cf_direction, (case when ccc.cf_direction = 'INFLOW' then '流入' else '流出' end) cf_direction_n, ccc.due_amount, ccc.received_amount, (ccc.due_amount - nvl(ccc.received_amount, 0)) residual_amount, nvl(ln.refund_amount, 0) refund_amount, nvl(ln.deduction_amount, 0) deduction_amount, (nvl(ln.refund_amount, 0) + nvl(ln.deduction_amount, 0)) occupy_amount, nvl((SELECT SUM(o.write_off_due_amount) FROM csh_write_off o WHERE o.cashflow_id = ccc.cashflow_id AND o.reversed_flag = 'N' AND o.write_off_type = 'REFUND'), 0) write_refund_amount, nvl((SELECT SUM(o.write_off_due_amount) FROM csh_write_off o, csh_transaction ct WHERE o.cashflow_id = ccc.cashflow_id AND o.reversed_flag = 'N' AND ct.transaction_id = o.csh_transaction_id AND o.write_off_type = 'PAYMENT_DEBT' AND ct.transaction_type = 'DEDUCTION'), 0) write_deduction_amount, case when (( ccc.due_amount - nvl( ccc.received_amount, 0 ) ) - nvl( ln.refund_amount, 0 ) - nvl( ln.deduction_amount, 0 )) < 0 then 0 else (( ccc.due_amount - nvl( ccc.received_amount, 0 ) ) - nvl( ln.refund_amount, 0 ) - nvl( ln.deduction_amount, 0 )) end RESIDUAL_AMOUNT_AFTER,
LN.DUE_AMOUNT_INTEREST FROM con_contract_cashflow ccc
LEFT JOIN (select * from hls_duration_ln l where l.hd_id = #{hdId}) ln ON ccc.cashflow_id = ln.cashflow_id LEFT JOIN con_contract cc on cc.contract_id = ccc.contract_id
ccc.cf_status = 'RELEASE'
and ccc.cf_item = #{cfItem}
and ccc.cf_item in (#{riskCfItem},54)
and cc.project_id = #{projectId}
and ccc.contract_id = #{contractId}
order by ccc.times

SELECT t1.*, (t1.pledge_proportion * t1.mortgage_amount_total) pledge_amount, (t1.mortgage_amount_total - nvl(t1.release_amount,t1.mortgage_amount_total)) release_amt FROM (SELECT t.project_id, i.lease_item_id, i.lease_item_code, i.full_name, (SELECT v.MEANING FROM sys_code_value_b_v v WHERE v.code = 'HLS.COLLATERAL_TYPE' AND v.code_value = i.lease_item_type) lease_item_type_n, (SELECT v.MEANING FROM sys_code_value_b_v v WHERE v.code = (CASE WHEN i.lease_item_type = 'MORTGAGE' THEN 'HLS.MORTGAGE_TYPE' ELSE 'HLS.PLEDGE_TYPE' END) AND v.code_value = i.pattern) pattern_n, (SELECT meaning FROM sys_code_value_b_v WHERE code = 'PLEDGE_STATE' AND code_value = i.pledge_state) pledge_state_n, i.mortgage_date_to, nvl(t.pledge_proportion, 0) pledge_proportion, nvl((SELECT SUM(nvl(d.mortgage_pledge_amount, 0)) FROM hls_lease_item_detail d left join hls_duration_ln ln on (ln.lease_item_detail_id = d.lease_item_detail_id and ln.source_type = 'RELEASE' and ln.hd_id = #{hdId}) WHERE d.lease_item_id = i.lease_item_id), 0) mortgage_amount_total, (SELECT SUM(nvl(ln.release_amount, 0)) FROM hls_duration_ln ln,hls_lease_item_detail d WHERE ln.source_type = 'RELEASE' and ln.hd_id = #{hdId} and ln.lease_item_detail_id = d.lease_item_detail_id and d.lease_item_id = i.lease_item_id) release_amount FROM prj_project_bp t, hls_lease_item i WHERE t.bp_type IN ('PLEDGOR', 'MORTGAGOR') AND t.lease_item_id = i.lease_item_id) t1
t1.project_id = #{projectId}
and t1.lease_item_id = #{leaseItemId}
order by t1.lease_item_code

select t1.* from ( SELECT t.lease_item_detail_id, t.lease_item_id, t.lease_full_name, nvl(t.quantity, 0) quantity, nvl(ln.release_flag, 'N') release_flag, (case when ln.release_flag = 'Y' then'是' else '否' end)release_flag_n, nvl(ln.release_quantity, 0) release_quantity, nvl(t.quantity, 0) - nvl(ln.release_quantity, 0) residual_quantity, nvl(t.mortgage_pledge_amount, 0) mortgage_pledge_amount, nvl(ln.release_amount, nvl(t.mortgage_pledge_amount, 0)) release_amount, t.net_asset_value as net_asset_value_now, t.remain_use_month, t.specification_model, ln.ln_id, ln.hd_id, (case when ln.release_flag = 'Y' then '1' else '2' end)order_seq FROM hls_lease_item_detail t LEFT JOIN (select * from hls_duration_ln l where l.hd_id = #{hdId}) ln ON t.lease_item_detail_id = ln.lease_item_detail_id)t1
t1.lease_item_id = #{leaseItemId}
order by order_seq,lease_full_name

select t1.* from ( SELECT t.lease_item_detail_id, t.lease_item_id, t.lease_full_name, nvl(t.quantity, 0) quantity, nvl(ln.release_flag, 'N') release_flag, (case when ln.release_flag = 'Y' then '是' else '否' end)release_flag_n, nvl(ln.release_quantity, 0) release_quantity, nvl(t.quantity, 0) - nvl(ln.release_quantity, 0) residual_quantity, nvl(t.mortgage_pledge_amount, 0) mortgage_pledge_amount, nvl(ln.release_amount, nvl(t.net_asset_value, 0)) release_amount, t.net_asset_value as net_asset_value_now, t.remain_use_month, t.specification_model, ln.ln_id, ln.hd_id, (case when ln.release_flag ='Y' then '1' else '2' end)order_seq FROM hls_lease_item_detail t LEFT JOIN (select * from hls_duration_ln l where l.hd_id = #{hdId}) ln ON t.lease_item_detail_id = ln.lease_item_detail_id)t1
t1.lease_item_id = #{leaseItemId}
order by order_seq,lease_full_name

mapper.delete:
delete
from hls_duration_ln ln
where
ln.hd_id = #{hdId}
and ln.source_type = #{sourceType}

    and exists (select 1 from hls_lease_item_detail t where t.lease_item_id = #{leaseItemId}
    and t.lease_item_detail_id = ln.lease_item_detail_id)


    and ln.warrant_id in

        #{item}

mapper.select:
select t1.* from (SELECT t.*, c.contract_number AS contract_id_n, c.finance_amount, (select hpl.description from hls_price_list hpl where hpl.price_list = t.et_price_list) et_price_list_n, (select hpl.description from hls_price_list hpl where hpl.price_list = t.prepayment_price_list) prepayment_price_list_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'EARLY_TERMINATION_CODE' AND v.code_value = t.et_type) et_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'EARLY_TERMINATION_CODE' AND v.code_value = t.prepayment_type) prepayment_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'SYS.YES_NO' AND v.code_value = t.prepayment_principal_flag) prepayment_principal_flag_n, (SELECT SUM(ccc.principal - nvl(ccc.received_principal, 0)) FROM con_contract_cashflow ccc WHERE ccc.contract_id = c.contract_id AND ccc.cf_item = 1 AND ccc.cf_status = 'RELEASE') AS residual_principal FROM hls_duration_ln t, con_contract c WHERE t.contract_id = c.contract_id AND t.source_type = 'ET')t1
and t1.hd_id = #{hdId}
and t1.ln_id = #{lnId}
order by t1.ln_id

select t1.* from (SELECT t.*, c.contract_number AS contract_id_n, c.finance_amount, (select hpl.description from hls_price_list hpl where hpl.price_list = t.et_price_list) et_price_list_n, (select hpl.description from hls_price_list hpl where hpl.price_list = t.prepayment_price_list) prepayment_price_list_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'EARLY_TERMINATION_CODE' AND v.code_value = t.et_type) et_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'EARLY_TERMINATION_CODE' AND v.code_value = t.prepayment_type) prepayment_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'SYS.YES_NO' AND v.code_value = t.prepayment_principal_flag) prepayment_principal_flag_n, (SELECT SUM(ccc.principal - nvl(ccc.received_principal, 0)) FROM con_contract_cashflow ccc WHERE ccc.contract_id = c.contract_id AND ccc.cf_item = 1 AND ccc.cf_status = 'RELEASE') AS residual_principal FROM hls_duration_ln t, con_contract c WHERE t.contract_id = c.contract_id AND t.source_type = 'ET')t1
t1.ln_id = #{lnId}
order by t1.ln_id

select t1.* from (SELECT t.*,(select hd.project_id from hls_duration_hd hd where hd.hd_id = t.hd_id) project_id, c.contract_number AS contract_id_n, c.finance_amount, (select hpl.description from hls_price_list hpl where hpl.price_list = t.et_price_list) et_price_list_n, (select hpl.description from hls_price_list hpl where hpl.price_list = t.prepayment_price_list) prepayment_price_list_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'EARLY_TERMINATION_CODE' AND v.code_value = t.et_type) et_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'EARLY_TERMINATION_CODE' AND v.code_value = t.prepayment_type) prepayment_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'SYS.YES_NO' AND v.code_value = nvl(t.prepayment_principal_flag,'N')) prepayment_principal_flag_n, (SELECT SUM(ccc.principal - nvl(ccc.received_principal, 0)) FROM con_contract_cashflow ccc WHERE ccc.contract_id = c.contract_id AND ccc.cf_item = 1 AND ccc.cf_status = 'RELEASE') AS residual_principal FROM hls_duration_ln t, con_contract c WHERE t.contract_id = c.contract_id AND t.source_type = 'PREPAYMENT')t1
and t1.hd_id = #{hdId}
and t1.ln_id = #{lnId}
order by t1.ln_id

select t1.* from (SELECT t.*,(select hd.project_id from hls_duration_hd hd where hd.hd_id = t.hd_id) project_id, c.contract_number AS contract_id_n, c.finance_amount, (select hpl.description from hls_price_list hpl where hpl.price_list = t.change_price_list)change_price_list_n, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'SYS.YES_NO' and sc.code_value = t.fine_reorganized_flag) fine_reorganized_flag_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'RENTING_FREQUENCY' AND v.code_value = t.alt_renting_frequency) alt_renting_frequency_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'PAY_TYPE' AND v.code_value = t.alt_pay_type) alt_pay_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'CALC_DATE_TYPE' AND v.code_value = t.alt_calc_date_type) alt_calc_date_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'RENTAL_ROUNDING_TYPE' AND v.code_value = t.alt_rental_rounding_type) alt_rental_rounding_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'HLS.ROLL_TYPE' AND v.code_value = t.roll_type) roll_type_n FROM hls_duration_ln t, con_contract c WHERE t.contract_id = c.contract_id AND t.source_type = 'FINANCIAL_TERMS')t1
and t1.hd_id = #{hdId}
and t1.ln_id = #{lnId}
order by t1.ln_id

select t1.* from (SELECT t.*, c.contract_number AS contract_id_n, (select q.finance_amount from prj_quotation q where q.quotation_id = c.quotation_id)finance_amount, c.base_rate_type, (select hpl.description from hls_price_list hpl where hpl.price_list = t.change_price_list)change_price_list_n, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'SYS.YES_NO' and sc.code_value = t.fine_reorganized_flag) fine_reorganized_flag_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'RENTING_FREQUENCY' AND v.code_value = t.alt_renting_frequency) alt_renting_frequency_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'PAY_TYPE' AND v.code_value = t.alt_pay_type) alt_pay_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'CALC_DATE_TYPE' AND v.code_value = t.alt_calc_date_type) alt_calc_date_type_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'RENTAL_ROUNDING_TYPE' AND v.code_value = t.alt_rental_rounding_type) alt_rental_rounding_type_n, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s. CODE = 'CON.INT_RATE_TYPE' AND s.code_value = t.ALT_INT_RATE_TYPE ) ALT_INT_RATE_TYPE_n, ( SELECT fb.DESCRIPTION AS value_name FROM fnd_base_rate_set fb WHERE fb.BASE_RATE_SET = t.ALT_BASE_RATE_COLLECT ) ALT_BASE_RATE_COLLECT_n, t.ALT_BASE_RATE_TYPE AS ALT_BASE_RATE_TYPE_n FROM hls_duration_ln t, con_contract c WHERE t.contract_id = c.contract_id AND t.source_type = 'FINANCIAL_TERMS')t1
t1.ln_id = #{lnId}
order by t1.ln_id
